// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListApiKeys API keys (secrets are never returned again)
	// (GET /api-keys)
	ListApiKeys(w http.ResponseWriter, r *http.Request)
	// CreateApiKey Create an API key; the secret is shown once
	// (POST /api-keys)
	CreateApiKey(w http.ResponseWriter, r *http.Request, params CreateApiKeyParams)
	// GetApiKeySelf Describe the API key used for this request
	// (GET /api-keys/whoami)
	GetApiKeySelf(w http.ResponseWriter, r *http.Request)
	// RevokeApiKey Revoke an API key immediately
	// (DELETE /api-keys/{apiKeyId})
	RevokeApiKey(w http.ResponseWriter, r *http.Request, apiKeyId ApiKeyId)
	// ListAuditLogs Audit trail, newest first
	// (GET /audit-logs)
	ListAuditLogs(w http.ResponseWriter, r *http.Request, params ListAuditLogsParams)
	// GetAuthCapabilities Which optional sign-in features are available
	// (GET /auth/capabilities)
	GetAuthCapabilities(w http.ResponseWriter, r *http.Request)
	// Login Sign in with e-mail and password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// LoginMfa Complete sign-in with a TOTP or recovery code
	// (POST /auth/login/mfa)
	LoginMfa(w http.ResponseWriter, r *http.Request)
	// Logout End the current session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset E-mail a password reset link
	// (POST /auth/password/forgot)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// ResetPassword Set a new password with a reset token
	// (POST /auth/password/reset)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// Reauthenticate Confirm identity before a sensitive action
	// (POST /auth/reauth)
	Reauthenticate(w http.ResponseWriter, r *http.Request)
	// ListWhatsAppAccounts Connected WhatsApp Business Accounts (credentials are never returned)
	// (GET /channels/accounts)
	ListWhatsAppAccounts(w http.ResponseWriter, r *http.Request)
	// ConnectWhatsAppAccount Connect a WhatsApp Business Account
	// (POST /channels/accounts)
	ConnectWhatsAppAccount(w http.ResponseWriter, r *http.Request, params ConnectWhatsAppAccountParams)
	// DisconnectWhatsAppAccount Disconnect an account without message history
	// (DELETE /channels/accounts/{accountId})
	DisconnectWhatsAppAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// UpdateWhatsAppAccount Rename, rotate credentials, or enable/disable an account
	// (PATCH /channels/accounts/{accountId})
	UpdateWhatsAppAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// SyncWhatsAppAccount Refresh phone numbers and templates from Meta
	// (POST /channels/accounts/{accountId}/sync)
	SyncWhatsAppAccount(w http.ResponseWriter, r *http.Request, accountId AccountId)
	// ListPhoneNumbers Phone numbers of every connected account
	// (GET /channels/phone-numbers)
	ListPhoneNumbers(w http.ResponseWriter, r *http.Request)
	// SetDefaultPhoneNumber Use this number when a request names no sender
	// (POST /channels/phone-numbers/{phoneNumberId}/default)
	SetDefaultPhoneNumber(w http.ResponseWriter, r *http.Request, phoneNumberId PhoneNumberId)
	// GetWebhookSetup Values to enter in the Meta App dashboard
	// (GET /channels/webhook)
	GetWebhookSetup(w http.ResponseWriter, r *http.Request)
	// ListInvitations Pending invitations
	// (GET /invitations)
	ListInvitations(w http.ResponseWriter, r *http.Request)
	// CreateInvitation Invite someone by e-mail
	// (POST /invitations)
	CreateInvitation(w http.ResponseWriter, r *http.Request, params CreateInvitationParams)
	// AcceptInvitation Accept an invitation and create the account
	// (POST /invitations/accept)
	AcceptInvitation(w http.ResponseWriter, r *http.Request)
	// LookupInvitation Show who an invitation token is for
	// (POST /invitations/lookup)
	LookupInvitation(w http.ResponseWriter, r *http.Request)
	// RevokeInvitation Revoke a pending invitation
	// (DELETE /invitations/{invitationId})
	RevokeInvitation(w http.ResponseWriter, r *http.Request, invitationId InvitationId)
	// GetMe The signed-in user, role, permissions and session
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Update profile
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// RegenerateRecoveryCodes Replace all recovery codes
	// (POST /me/mfa/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// DisableTotp Turn off two-factor authentication
	// (DELETE /me/mfa/totp)
	DisableTotp(w http.ResponseWriter, r *http.Request)
	// StartTotpSetup Generate a TOTP secret to enrol an authenticator app
	// (POST /me/mfa/totp)
	StartTotpSetup(w http.ResponseWriter, r *http.Request)
	// ConfirmTotp Activate TOTP with a code from the app; returns recovery codes once
	// (POST /me/mfa/totp/confirm)
	ConfirmTotp(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change password; ends every other session
	// (POST /me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// RevokeOtherSessions End every session except the current one
	// (DELETE /me/sessions)
	RevokeOtherSessions(w http.ResponseWriter, r *http.Request)
	// ListMySessions Active sessions of the signed-in user
	// (GET /me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// RevokeMySession End one of the user's sessions
	// (DELETE /me/sessions/{sessionId})
	RevokeMySession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// SendMessage Queue a WhatsApp message
	// (POST /messages)
	SendMessage(w http.ResponseWriter, r *http.Request, params SendMessageParams)
	// GetMessage A message and its delivery state
	// (GET /messages/{messageId})
	GetMessage(w http.ResponseWriter, r *http.Request, messageId MessageId)
	// ListRoles Roles and the permissions they grant
	// (GET /roles)
	ListRoles(w http.ResponseWriter, r *http.Request)
	// GetSettings Workspace settings
	// (GET /settings)
	GetSettings(w http.ResponseWriter, r *http.Request)
	// UpdateSettings Change workspace settings
	// (PATCH /settings)
	UpdateSettings(w http.ResponseWriter, r *http.Request)
	// CompleteSetup Create the first owner account with the one-time setup token
	// (POST /setup)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// GetSetupStatus Whether the first owner account still has to be created
	// (GET /setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// GetSystemStatus Health of every component of the installation
	// (GET /system/status)
	GetSystemStatus(w http.ResponseWriter, r *http.Request)
	// ListTemplates Message templates mirrored from Meta
	// (GET /templates)
	ListTemplates(w http.ResponseWriter, r *http.Request, params ListTemplatesParams)
	// CreateTemplate Submit a template for Meta's review
	// (POST /templates)
	CreateTemplate(w http.ResponseWriter, r *http.Request, params CreateTemplateParams)
	// DeleteTemplate Delete one language version of a template on Meta and locally
	// (DELETE /templates/{templateId})
	DeleteTemplate(w http.ResponseWriter, r *http.Request, templateId TemplateId)
	// ListUsers All panel users
	// (GET /users)
	ListUsers(w http.ResponseWriter, r *http.Request)
	// UpdateUser Change a user's role or status
	// (PATCH /users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId UserId)
}

